CREATE TABLE progresso_aluno(user_id BIGINT PRIMARY KEY REFERENCES users(id),xp BIGINT NOT NULL DEFAULT 0,streak INTEGER NOT NULL DEFAULT 0,seconds INTEGER NOT NULL DEFAULT 0,usage_day DATE,qualified_day DATE,last_beat TIMESTAMP WITH TIME ZONE);
CREATE TABLE historico_xp(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),task_id BIGINT NOT NULL,amount INTEGER NOT NULL,earned_at TIMESTAMP WITH TIME ZONE,UNIQUE(user_id,task_id));
CREATE TABLE conquistas_aluno(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),code VARCHAR(255) NOT NULL,earned_at TIMESTAMP WITH TIME ZONE,UNIQUE(user_id,code));
